class DynamicArray {
  constructor() {
    this.capacity = 2;
    this.size = 0;
    this.data = new Array(this.capacity);
  }

  // Get element
  get(index) {
    if (index < 0 || index >= this.size) {
      throw new Error("Index out of bounds");
    }
    return this.data[index];
  }

  // Set element
  set(index, value) {
    if (index < 0 || index >= this.size) {
      throw new Error("Index out of bounds");
    }
    this.data[index] = value;
  }

  // Add element to end
  push(value) {
    // Check if resize is needed
    if (this.size >= this.capacity) {
      this.resize();
    }

    this.data[this.size] = value;
    this.size++;
  }

  // Remove last element
  pop() {
    if (this.size === 0) {
      throw new Error("Array is empty");
    }

    const value = this.data[this.size - 1];
    this.size--;

    // Optional: shrink to save memory
    if (this.size < this.capacity / 4) {
      this.shrink();
    }

    return value;
  }

  // Resize (expand)
  resize() {
    const oldCapacity = this.capacity;
    this.capacity *= 2;
    const newData = new Array(this.capacity);

    // Copy old data
    for (let i = 0; i < this.size; i++) {
      newData[i] = this.data[i];
    }

    this.data = newData;
    console.log(`Expanded: ${oldCapacity} -> ${this.capacity}`);
  }

  // Shrink (reduce capacity)
  shrink() {
    if (this.capacity <= 2) return;

    const oldCapacity = this.capacity;
    this.capacity = Math.floor(this.capacity / 2);
    const newData = new Array(this.capacity);

    for (let i = 0; i < this.size; i++) {
      newData[i] = this.data[i];
    }

    this.data = newData;
    console.log(`Shrunk: ${oldCapacity} -> ${this.capacity}`);
  }

  // Insert element at specified position
  insert(index, value) {
    if (index < 0 || index > this.size) {
      throw new Error("Index out of bounds");
    }

    if (this.size >= this.capacity) {
      this.resize();
    }

    // Shift elements to the right
    for (let i = this.size; i > index; i--) {
      this.data[i] = this.data[i - 1];
    }

    this.data[index] = value;
    this.size++;
  }

  // 删除指定位置的元素
  remove(index) {
    if (index < 0 || index >= this.size) {
      throw new Error("Index out of bounds");
    }

    const value = this.data[index];

    // 向左移动元素
    for (let i = index; i < this.size - 1; i++) {
      this.data[i] = this.data[i + 1];
    }

    this.size--;

    if (this.size < this.capacity / 4) {
      this.shrink();
    }

    return value;
  }

  length() {
    return this.size;
  }

  toString() {
    const elements = [];
    for (let i = 0; i < this.size; i++) {
      elements.push(this.data[i]);
    }
    return `[${elements.join(", ")}] (size: ${this.size}, capacity: ${this.capacity})`;
  }
}
